289	void CollectionImpl::prepare_schema() {
290	  // set default index params for vector fields
291	  for (auto &field : schema_->fields()) {
292	    if (field->is_vector_field()) {
293	      if (field->index_params() == nullptr) {
294	        field->set_index_params(DefaultVectorIndexParams);
295	      }
296	    }
297	  }
298	}
