308	Status CollectionImpl::Open(const CollectionOptions &options) {
309	  options_ = options;
310	
311	  if (schema_ != nullptr && options_.read_only_) {
312	    return Status::InvalidArgument(
313	        "Unable to create collection with read-only mode.");
314	  }
315	
316	  Status s;
317	  if (schema_ == nullptr) {
318	    // recovery from disk
319	    s = recovery();
320	  } else {
321	    // create new collection with existing schema
322	    s = create();
323	  }
324	
325	  auto profiler = std::make_shared<Profiler>();
326	  sql_engine_ = sqlengine::SQLEngine::create(profiler);
327	
328	  return s;
329	}
330	
331	Status CollectionImpl::Close() {
332	  // only called in deconstructor
333	  std::lock_guard lock(schema_handle_mtx_);
334	
335	  CHECK_DESTROY_RETURN_STATUS(destroyed_, false);
336	
337	  return close_unsafe();
338	}
339	
340	Status CollectionImpl::close_unsafe() {
341	  Status result = Status::OK();
342	
343	  // flush
344	  if (!options_.read_only_) {
345	    auto s = flush_unsafe();
346	    if (!s.ok()) {
347	      result = s;
348	    }
349	  }
350	
351	  // always release resources regardless of flush outcome
352	  writing_segment_.reset();
353	  segment_manager_.reset();
354	  version_manager_.reset();
355	  id_map_.reset();
356	  delete_store_.reset();
357	
358	  lock_file_.close();
359	
360	  return result;
361	}
