403	Result<CollectionStats> CollectionImpl::Stats() const {
404	  std::lock_guard lock(schema_handle_mtx_);
405	
406	  CHECK_DESTROY_RETURN_STATUS_EXPECTED(destroyed_, false);
407	
408	  auto segments = get_all_segments();
409	
410	  CollectionStats stats;
411	  auto vector_fields = schema_->vector_fields();
412	  if (segments.empty()) {
413	    stats.doc_count = 0;
414	    for (auto &field : vector_fields) {
415	      stats.index_completeness[field->name()] =
416	          1;  // if no doc, completeness is 1
417	    }
418	    return stats;
419	  }
420	
421	  for (auto &segment : segments) {
422	    stats.doc_count += segment->doc_count(delete_store_->make_filter());
423	  }
424	
425	  for (auto &field : vector_fields) {
426	    if (stats.doc_count == 0) {
427	      stats.index_completeness[field->name()] = 1;
428	      continue;
429	    }
430	
431	    uint32_t indexed_doc_count{0};
432	    for (auto &segment : segments) {
433	      if (segment->meta()->vector_indexed(field->name())) {
434	        indexed_doc_count += segment->doc_count(delete_store_->make_filter());
435	      }
436	    }
437	    stats.index_completeness[field->name()] =
438	        indexed_doc_count * 1.0 / stats.doc_count;
439	  }
440	
441	  return stats;
442	}
