460	Status CollectionImpl::CreateIndex(const std::string &column_name,
461	                                   const IndexParams::Ptr &index_params,
462	                                   const CreateIndexOptions &options) {
463	  CHECK_COLLECTION_READONLY_RETURN_STATUS;
464	
465	  std::lock_guard lock(schema_handle_mtx_);
466	
467	  CHECK_DESTROY_RETURN_STATUS(destroyed_, false);
468	
469	  if (index_params == nullptr) {
470	    return Status::InvalidArgument("CreateIndex: index_params is null");
471	  }
472	
473	  auto new_schema = std::make_shared<CollectionSchema>(*schema_);
474	  auto s = new_schema->add_index(column_name, index_params);
475	  CHECK_RETURN_STATUS(s);
476	  s = new_schema->validate();
477	  CHECK_RETURN_STATUS(s);
478	
479	  auto field = schema_->get_field(column_name);
480	  if (field->index_params() != nullptr &&
481	      *field->index_params() == *index_params) {
482	    // equal index params
483	    return Status::OK();
484	  }
485	
486	  // Reject creating a non-vector index when the column already has a different
487	  // non-vector index type (e.g. adding FTS when INVERT exists, or vice versa).
488	  if (!field->is_vector_field() && field->index_params() != nullptr &&
489	      field->index_params()->type() != index_params->type()) {
490	    return Status::NotSupported(
491	        "CreateIndex: column[", column_name, "] already has index type [",
492	        IndexTypeCodeBook::AsString(field->index_params()->type()),
493	        "], cannot create index type [",
494	        IndexTypeCodeBook::AsString(index_params->type()),
495	        "] on the same column");
496	  }
497	
498	  // forbidden writing until index is ready
499	  std::lock_guard write_lock(write_mtx_);
500	
501	  if (writing_segment_->doc_count() > 0) {
502	    s = switch_to_new_segment_for_writing();
503	    CHECK_RETURN_STATUS(s);
504	  }
505	
506	  auto old_writing_segment = writing_segment_;
507	  Version old_version = version_manager_->get_current_version();
508	  Version new_version = old_version;
509	  auto writing_min_doc_id = old_writing_segment->meta()->min_doc_id();
510	
511	  // DDL tasks only run on persisted segments. Non-empty writing segment has
512	  // already been switched to a persisted segment above.
513	  auto persist_segments = get_all_persist_segments();
514	
515	  bool is_vector_field = field->is_vector_field();
516	
517	  std::vector<SegmentTask::Ptr> tasks;
518	  if (is_vector_field) {
519	    tasks = build_create_vector_index_task(persist_segments, column_name,
520	                                           index_params, options.concurrency_);
521	  } else if (index_params->type() == IndexType::INVERT) {
522	    tasks = build_create_scalar_index_task(persist_segments, column_name,
523	                                           index_params, options.concurrency_);
524	  } else if (index_params->type() == IndexType::FTS) {
525	    tasks = build_create_fts_index_task(persist_segments, column_name,
526	                                        index_params);
527	  } else {
528	    return Status::NotSupported(
529	        "CreateIndex: index type [",
530	        IndexTypeCodeBook::AsString(index_params->type()),
531	        "] is not supported");
532	  }
533	
534	  if (!tasks.empty()) {
535	    s = execute_tasks(tasks);
536	    CHECK_RETURN_STATUS(s);
537	  }
538	
539	  new_version.set_schema(*new_schema);
540	
541	  for (auto &task : tasks) {
542	    auto task_info = task->task_info();
543	
544	    if (std::holds_alternative<CreateVectorIndexTask>(task_info)) {
545	      auto create_index_task = std::get<CreateVectorIndexTask>(task_info);
546	      s = new_version.update_persisted_segment_meta(
547	          create_index_task.output_segment_meta_);
548	    } else if (std::holds_alternative<CreateScalarIndexTask>(task_info)) {
549	      auto create_index_task = std::get<CreateScalarIndexTask>(task_info);
550	      s = new_version.update_persisted_segment_meta(
551	          create_index_task.output_segment_meta_);
552	    } else if (std::holds_alternative<CreateFtsIndexTask>(task_info)) {
553	      auto fts_task = std::get<CreateFtsIndexTask>(task_info);
554	      s = new_version.update_persisted_segment_meta(
555	          fts_task.output_segment_meta_);
556	    }
557	    CHECK_RETURN_STATUS(s);
558	  }
559	
560	  s = commit_schema_change_with_new_writing_segment(
561	      new_schema, old_writing_segment, old_version, &new_version,
562	      writing_min_doc_id);
563	  CHECK_RETURN_STATUS(s);
564	
565	  // 4. remove old segments or block
566	  for (auto &task : tasks) {
567	    auto task_info = task->task_info();
568	
569	    if (std::holds_alternative<CreateVectorIndexTask>(task_info)) {
570	      auto create_index_task = std::get<CreateVectorIndexTask>(task_info);
571	      s = create_index_task.input_segment_->reload_vector_index(
572	          *new_schema, create_index_task.output_segment_meta_,
573	          create_index_task.output_vector_indexers_,
574	          create_index_task.output_quant_vector_indexers_);
575	    } else if (std::holds_alternative<CreateScalarIndexTask>(task_info)) {
576	      auto create_index_task = std::get<CreateScalarIndexTask>(task_info);
577	      s = create_index_task.input_segment_->reload_scalar_index(
578	          *new_schema, create_index_task.output_segment_meta_,
579	          create_index_task.output_scalar_indexer_);
580	    } else if (std::holds_alternative<CreateFtsIndexTask>(task_info)) {
581	      auto fts_task = std::get<CreateFtsIndexTask>(task_info);
582	      s = fts_task.input_segment_->reload_fts_index(
583	          *new_schema, fts_task.output_segment_meta_,
584	          fts_task.output_fts_indexer_);
585	    }
586	    CHECK_RETURN_STATUS(s);
587	  }
588	
589	  return Status::OK();
590	}
