592	std::vector<SegmentTask::Ptr> CollectionImpl::build_create_vector_index_task(
593	    const std::vector<Segment::Ptr> &segments, const std::string &column,
594	    const IndexParams::Ptr &index_params, int concurrency) {
595	  std::vector<SegmentTask::Ptr> tasks;
596	  for (auto &segment : segments) {
597	    if (!segment->vector_index_ready(column, index_params)) {
598	      tasks.push_back(SegmentTask::CreateCreateVectorIndexTask(
599	          CreateVectorIndexTask{segment, column, index_params, concurrency}));
600	    }
601	  }
602	  return tasks;
603	}
