650	Status CollectionImpl::DropIndex(const std::string &column_name) {
651	  CHECK_COLLECTION_READONLY_RETURN_STATUS;
652	
653	  std::lock_guard lock(schema_handle_mtx_);
654	
655	  CHECK_DESTROY_RETURN_STATUS(destroyed_, false);
656	
657	  auto new_schema = std::make_shared<CollectionSchema>(*schema_);
658	  auto s = new_schema->drop_index(column_name);
659	  CHECK_RETURN_STATUS(s);
660	
661	  auto field = schema_->get_field(column_name);
662	  if (field->index_params() == nullptr) {
663	    return Status::OK();  // return ok if not indexed
664	  }
665	
666	  if (field->is_vector_field() &&
667	      *field->index_params() == DefaultVectorIndexParams) {
668	    return Status::OK();
669	  }
670	
671	  // forbidden writing until index is ready
672	  std::lock_guard write_lock(write_mtx_);
673	
674	  if (writing_segment_->doc_count() > 0) {
675	    s = switch_to_new_segment_for_writing();
676	    CHECK_RETURN_STATUS(s);
677	  }
678	
679	  auto old_writing_segment = writing_segment_;
680	  Version old_version = version_manager_->get_current_version();
681	  Version new_version = old_version;
682	  auto writing_min_doc_id = old_writing_segment->meta()->min_doc_id();
683	
684	  auto persist_segments = get_all_persist_segments();
685	
686	  bool is_vector_field = field->is_vector_field();
687	
688	  std::vector<SegmentTask::Ptr> tasks;
689	  if (is_vector_field) {
690	    tasks = build_drop_vector_index_task(persist_segments, column_name);
691	  } else if (field->index_params()->type() == IndexType::INVERT) {
692	    tasks = build_drop_scalar_index_task(persist_segments, column_name);
693	  } else if (field->index_params()->type() == IndexType::FTS) {
694	    tasks = build_drop_fts_index_task(persist_segments, column_name);
695	  } else {
696	    return Status::NotSupported(
697	        "DropIndex: index type [",
698	        IndexTypeCodeBook::AsString(field->index_params()->type()),
699	        "] on column[", column_name, "] is not supported");
700	  }
701	
702	  if (!tasks.empty()) {
703	    s = execute_tasks(tasks);
704	    CHECK_RETURN_STATUS(s);
705	  }
706	
707	  new_version.set_schema(*new_schema);
708	
709	  for (auto &task : tasks) {
710	    auto task_info = task->task_info();
711	
712	    if (std::holds_alternative<DropVectorIndexTask>(task_info)) {
713	      auto drop_index_task = std::get<DropVectorIndexTask>(task_info);
714	      s = new_version.update_persisted_segment_meta(
715	          drop_index_task.output_segment_meta_);
716	    } else if (std::holds_alternative<DropScalarIndexTask>(task_info)) {
717	      auto drop_index_task = std::get<DropScalarIndexTask>(task_info);
718	      s = new_version.update_persisted_segment_meta(
719	          drop_index_task.output_segment_meta_);
720	    } else if (std::holds_alternative<DropFtsIndexTask>(task_info)) {
721	      auto fts_task = std::get<DropFtsIndexTask>(task_info);
722	      s = new_version.update_persisted_segment_meta(
723	          fts_task.output_segment_meta_);
724	    }
725	    CHECK_RETURN_STATUS(s);
726	  }
727	
728	  s = commit_schema_change_with_new_writing_segment(
729	      new_schema, old_writing_segment, old_version, &new_version,
730	      writing_min_doc_id);
731	  CHECK_RETURN_STATUS(s);
732	
733	  // 4. remove old segments or block
734	  for (auto &task : tasks) {
735	    auto task_info = task->task_info();
736	
737	    if (std::holds_alternative<DropVectorIndexTask>(task_info)) {
738	      auto drop_index_task = std::get<DropVectorIndexTask>(task_info);
739	      s = drop_index_task.input_segment_->reload_vector_index(
740	          *new_schema, drop_index_task.output_segment_meta_,
741	          drop_index_task.output_vector_indexers_);
742	    } else if (std::holds_alternative<DropScalarIndexTask>(task_info)) {
743	      auto drop_index_task = std::get<DropScalarIndexTask>(task_info);
744	      s = drop_index_task.input_segment_->reload_scalar_index(
745	          *new_schema, drop_index_task.output_segment_meta_,
746	          drop_index_task.output_scalar_indexer_);
747	    } else if (std::holds_alternative<DropFtsIndexTask>(task_info)) {
748	      auto fts_task = std::get<DropFtsIndexTask>(task_info);
749	      s = fts_task.input_segment_->reload_fts_index(
750	          *new_schema, fts_task.output_segment_meta_,
751	          fts_task.output_fts_indexer_);
752	    }
753	    CHECK_RETURN_STATUS(s);
754	  }
755	
756	  return Status::OK();
757	}
