1208	Status CollectionImpl::DropColumn(const std::string &column_name) {
1209	  CHECK_COLLECTION_READONLY_RETURN_STATUS;
1210	
1211	  std::lock_guard lock(schema_handle_mtx_);
1212	
1213	  CHECK_DESTROY_RETURN_STATUS(destroyed_, false);
1214	
1215	  // validate
1216	  auto s = validate(column_name, nullptr, "", "", ColumnOp::DROP);
1217	  CHECK_RETURN_STATUS(s);
1218	
1219	  // forbidden writing until index is ready
1220	  std::lock_guard write_lock(write_mtx_);
1221	
1222	  auto new_schema = std::make_shared<CollectionSchema>(*schema_);
1223	  s = new_schema->drop_field(column_name);
1224	  CHECK_RETURN_STATUS(s);
1225	
1226	  if (writing_segment_->doc_count() > 0) {
1227	    s = switch_to_new_segment_for_writing();
1228	    CHECK_RETURN_STATUS(s);
1229	  }
1230	
1231	  Version new_version = version_manager_->get_current_version();
1232	
1233	  // drop column on segment manager
1234	  s = segment_manager_->drop_column(column_name);
1235	  CHECK_RETURN_STATUS(s);
1236	
1237	  // reset writing segment with new schema
1238	  auto id = writing_segment_->id();
1239	  auto min_doc_id = writing_segment_->meta()->min_doc_id();
1240	
1241	  s = writing_segment_->destroy();
1242	  CHECK_RETURN_STATUS(s);
1243	  writing_segment_.reset();
1244	
1245	  SegmentOptions seg_options;
1246	  seg_options.enable_mmap_ = options_.enable_mmap_;
1247	  seg_options.max_buffer_size_ = options_.max_buffer_size_;
1248	  seg_options.read_only_ = options_.read_only_;
1249	  auto writing_segment =
1250	      Segment::CreateAndOpen(path_, *new_schema, id, min_doc_id, id_map_,
1251	                             delete_store_, version_manager_, seg_options);
1252	  if (!writing_segment) {
1253	    return writing_segment.error();
1254	  }
1255	  writing_segment_ = writing_segment.value();
1256	
1257	  // update new version
1258	  new_version.set_schema(*new_schema);
1259	  new_version.reset_writing_segment_meta(writing_segment_->meta());
1260	
1261	  auto new_segment_metas = segment_manager_->get_segments_meta();
1262	  for (auto meta : new_segment_metas) {
1263	    s = new_version.update_persisted_segment_meta(meta);
1264	    CHECK_RETURN_STATUS(s);
1265	  }
1266	
1267	  s = version_manager_->apply(new_version);
1268	  CHECK_RETURN_STATUS(s);
1269	
1270	  // persist manifest
1271	  s = version_manager_->flush();
1272	  CHECK_RETURN_STATUS(s);
1273	
1274	  schema_ = new_schema;
1275	
1276	  return Status::OK();
1277	}
