1279	Status CollectionImpl::AlterColumn(const std::string &column_name,
1280	                                   const std::string &rename,
1281	                                   const FieldSchema::Ptr &new_column_schema,
1282	                                   const AlterColumnOptions &options) {
1283	  CHECK_COLLECTION_READONLY_RETURN_STATUS;
1284	
1285	  std::lock_guard lock(schema_handle_mtx_);
1286	
1287	  CHECK_DESTROY_RETURN_STATUS(destroyed_, false);
1288	
1289	  // validate
1290	  auto s =
1291	      validate(column_name, new_column_schema, "", rename, ColumnOp::ALTER);
1292	  CHECK_RETURN_STATUS(s);
1293	
1294	  // forbidden writing until index is ready
1295	  std::lock_guard write_lock(write_mtx_);
1296	
1297	  std::shared_ptr<FieldSchema> new_field_schema{nullptr};
1298	  if (!rename.empty()) {
1299	    new_field_schema =
1300	        std::make_shared<FieldSchema>(*schema_->get_field(column_name));
1301	    new_field_schema->set_name(rename);
1302	  } else {
1303	    new_field_schema = std::make_shared<FieldSchema>(*new_column_schema);
1304	  }
1305	
1306	  auto new_schema = std::make_shared<CollectionSchema>(*schema_);
1307	  s = new_schema->alter_field(column_name, new_field_schema);
1308	  CHECK_RETURN_STATUS(s);
1309	
1310	  if (writing_segment_->doc_count() > 0) {
1311	    s = switch_to_new_segment_for_writing();
1312	    CHECK_RETURN_STATUS(s);
1313	  }
1314	
1315	  Version new_version = version_manager_->get_current_version();
1316	
1317	  // alter column on segment manager
1318	  s = segment_manager_->alter_column(column_name, new_field_schema,
1319	                                     options.concurrency_);
1320	  CHECK_RETURN_STATUS(s);
1321	
1322	  // reset writing segment with new schema
1323	  auto id = writing_segment_->id();
1324	  auto min_doc_id = writing_segment_->meta()->min_doc_id();
1325	
1326	  s = writing_segment_->destroy();
1327	  CHECK_RETURN_STATUS(s);
1328	  writing_segment_.reset();
1329	
1330	  SegmentOptions seg_options;
1331	  seg_options.enable_mmap_ = options_.enable_mmap_;
1332	  seg_options.max_buffer_size_ = options_.max_buffer_size_;
1333	  seg_options.read_only_ = options_.read_only_;
1334	  auto writing_segment =
1335	      Segment::CreateAndOpen(path_, *new_schema, id, min_doc_id, id_map_,
1336	                             delete_store_, version_manager_, seg_options);
1337	  if (!writing_segment) {
1338	    return writing_segment.error();
1339	  }
1340	  writing_segment_ = writing_segment.value();
1341	
1342	  // update new version
1343	  new_version.set_schema(*new_schema);
1344	  new_version.reset_writing_segment_meta(writing_segment_->meta());
1345	
1346	  auto new_segment_metas = segment_manager_->get_segments_meta();
1347	  for (auto meta : new_segment_metas) {
1348	    s = new_version.update_persisted_segment_meta(meta);
1349	    CHECK_RETURN_STATUS(s);
1350	  }
1351	
1352	  s = version_manager_->apply(new_version);
1353	  CHECK_RETURN_STATUS(s);
1354	
1355	  // persist manifest
1356	  s = version_manager_->flush();
1357	  CHECK_RETURN_STATUS(s);
1358	
1359	  schema_ = new_schema;
1360	
1361	  return Status::OK();
1362	}
