1376	Status CollectionImpl::internal_fetch_by_doc(const Doc &doc,
1377	                                             Doc::Ptr *doc_out) {
1378	  auto segments = get_all_segments();
1379	  uint64_t doc_id;
1380	  bool has = id_map_->has(doc.pk(), &doc_id);
1381	  if (!has) {
1382	    return Status::NotFound("Document not found");
1383	  }
1384	  if (delete_store_->is_deleted(doc_id)) {
1385	    return Status::NotFound("Document already deleted");
1386	  }
1387	
1388	  auto segment = local_segment_by_doc_id(doc_id, segments);
1389	  if (!segment) {
1390	    LOG_WARN("doc_id: %zu segment not found", (size_t)doc_id);
1391	    return Status::InternalError("Segment not found");
1392	  }
1393	
1394	  auto old_doc = segment->Fetch(doc_id, std::nullopt, true);
1395	  if (!old_doc) {
1396	    LOG_WARN("doc_id: %zu fetch doc failed", (size_t)doc_id);
1397	    return Status::InternalError("Fetch doc failed");
1398	  }
1399	  *doc_out = old_doc;
1400	  return Status::OK();
1401	}
