1476	Status CollectionImpl::commit_schema_change_with_new_writing_segment(
1477	    const CollectionSchema::Ptr &new_schema,
1478	    const Segment::Ptr &old_writing_segment, const Version &old_version,
1479	    Version *new_version, uint64_t writing_min_doc_id) {
1480	  if (new_version == nullptr) {
1481	    return Status::InvalidArgument("new_version is null");
1482	  }
1483	
1484	  auto seg_options =
1485	      SegmentOptions{false, options_.enable_mmap_, options_.max_buffer_size_};
1486	  auto new_writing_segment = Segment::CreateAndOpen(
1487	      path_, *new_schema, allocate_segment_id(), writing_min_doc_id, id_map_,
1488	      delete_store_, version_manager_, seg_options);
1489	  if (!new_writing_segment) {
1490	    return new_writing_segment.error();
1491	  }
1492	  new_version->reset_writing_segment_meta(new_writing_segment.value()->meta());
1493	  new_version->set_next_segment_id(segment_id_allocator_.load());
1494	
1495	  auto s = version_manager_->apply(*new_version);
1496	  if (!s.ok()) {
1497	    new_writing_segment.value()->destroy();
1498	    return s;
1499	  }
1500	
1501	  s = version_manager_->flush();
1502	  if (!s.ok()) {
1503	    new_writing_segment.value()->destroy();
1504	    auto rollback_status = version_manager_->apply(old_version);
1505	    CHECK_RETURN_STATUS(rollback_status);
1506	    return s;
1507	  }
1508	
1509	  schema_ = new_schema;
1510	  writing_segment_ = new_writing_segment.value();
1511	  s = old_writing_segment->destroy();
1512	  CHECK_RETURN_STATUS(s);
1513	
1514	  return Status::OK();
1515	}
