197	//! Return 1 if success or 0 if eof or -1 if read error
198	int LocalWalFile::read_record(WalRecord &record) {
199	  CHECK_STATUS(opened_, true);
200	
201	  int read_size = 0;
202	  std::string err_msg;
203	  int ret = -1;
204	
205	  do {
206	    read_size =
207	        file_.read(reinterpret_cast<void *>(&record.length_), LENGTH_SIZE);
208	    if (read_size == 0) {
209	      ret = 0;
210	      WLOG_INFO("Wal read finished. end of file");
211	      break;
212	    }
213	
214	    if (read_size != LENGTH_SIZE) {
215	      WLOG_ERROR("Wal read error. record.length_ error read_size[%d]",
216	                 read_size);
217	      break;
218	    }
219	
220	    read_size = file_.read(reinterpret_cast<void *>(&record.crc_), CRC_SIZE);
221	    if (read_size != CRC_SIZE) {
222	      WLOG_ERROR("Wal read error. record.crc_ error read_size[%d]", read_size);
223	      break;
224	    }
225	
226	    // resize may crash if record.length_ very large
227	    if (record.length_ <= 0 || record.length_ > MAX_RECORD_SIZE) {
228	      WLOG_ERROR("Wal read error. record.length_ value error read_size[%d]",
229	                 read_size);
230	      break;
231	    }
232	
233	    record.content_.resize(record.length_);
234	    read_size = file_.read((void *)const_cast<char *>(record.content_.data()),
235	                           record.length_);
236	    if (read_size != (int)record.length_) {
237	      WLOG_ERROR("Wal read error. record.content_ error read_size[%d]",
238	                 read_size);
239	      break;
240	    }
241	    ret = 1;  // read one record success
242	  } while (false);
243	
244	  return ret;
245	}
