36	Status RocksdbContext::create(Args args) {
37	  per_cf_merge_ops_ = std::move(args.per_cf_merge_ops);
38	  enable_hash_skiplist_ = args.enable_hash_skiplist;
39	
40	  std::lock_guard<std::mutex> lock(mutex_);
41	
42	  if (db_) {
43	    LOG_ERROR("RocksDB[%s] is already opened", db_path_.c_str());
44	    return Status::PermissionDenied();
45	  }
46	
47	  if (auto s = validate_and_set_db_path(args.db_path, false); !s.ok()) {
48	    return s;
49	  }
50	
51	  create_opts_.create_if_missing = true;
52	  prepare_options(std::move(args.merge_op));
53	
54	  rocksdb::DB *db;
55	  rocksdb::Status s = rocksdb::DB::Open(create_opts_, args.db_path, &db);
56	  if (!s.ok()) {
57	    LOG_ERROR("Failed to create RocksDB[%s], code[%d], reason[%s]",
58	              args.db_path.c_str(), s.code(), s.ToString().c_str());
59	    return Status::InternalError();
60	  }
61	  db_.reset(db);
62	
63	  bool has_default = false;
64	  for (const auto &column_name : args.column_names) {
65	    if (column_name == rocksdb::kDefaultColumnFamilyName) {
66	      cf_handles_.push_back(db->DefaultColumnFamily());
67	      has_default = true;
68	      continue;
69	    }
70	    rocksdb::ColumnFamilyHandle *cf_handle{nullptr};
71	    rocksdb::ColumnFamilyOptions cf_options(create_opts_);
72	    auto it = per_cf_merge_ops_.find(column_name);
73	    if (it != per_cf_merge_ops_.end() && it->second) {
74	      cf_options.merge_operator = it->second;
75	    }
76	    s = db->CreateColumnFamily(cf_options, column_name, &cf_handle);
77	    if (!s.ok()) {
78	      LOG_ERROR("Failed to create cf[%s] in RocksDB[%s], code[%d], reason[%s]",
79	                column_name.c_str(), args.db_path.c_str(), s.code(),
80	                s.ToString().c_str());
81	      delete_cf_handles();
82	      db->Close();
83	      db_.reset();
84	      return Status::InternalError();
85	    }
86	    cf_handles_.push_back(cf_handle);
87	  }
88	  if (!has_default) {
89	    cf_handles_.push_back(db->DefaultColumnFamily());
90	  }
91	
92	  read_only_ = false;
93	  write_opts_.disableWAL = true;
94	  LOG_DEBUG("Created RocksDB[%s] with Args", args.db_path.c_str());
95	  return Status::OK();
96	}
