112	Status RocksdbContext::open(Args args, bool read_only) {
113	  per_cf_merge_ops_ = std::move(args.per_cf_merge_ops);
114	  enable_hash_skiplist_ = args.enable_hash_skiplist;
115	
116	  std::lock_guard<std::mutex> lock(mutex_);
117	
118	  if (db_) {
119	    LOG_ERROR("RocksDB[%s] is already opened", db_path_.c_str());
120	    return Status::PermissionDenied();
121	  }
122	
123	  if (auto s = validate_and_set_db_path(args.db_path, true); !s.ok()) {
124	    return s;
125	  }
126	
127	  create_opts_.create_if_missing = false;
128	  prepare_options(std::move(args.merge_op));
129	
130	  rocksdb::Status s;
131	  std::vector<std::string> existing_cf_names{};
132	  std::vector<rocksdb::ColumnFamilyDescriptor> cf_descriptors{};
133	  s = rocksdb::DB::ListColumnFamilies(create_opts_, args.db_path,
134	                                      &existing_cf_names);
135	  if (!s.ok()) {
136	    LOG_ERROR("Failed to list cf in RocksDB[%s], code[%d], reason[%s]",
137	              args.db_path.c_str(), s.code(), s.ToString().c_str());
138	    return Status::InternalError();
139	  }
140	
141	  auto make_cf_options = [&](const std::string &cf_name) {
142	    rocksdb::ColumnFamilyOptions cf_options(create_opts_);
143	    auto it = per_cf_merge_ops_.find(cf_name);
144	    if (it != per_cf_merge_ops_.end() && it->second) {
145	      cf_options.merge_operator = it->second;
146	    }
147	    return cf_options;
148	  };
149	
150	  if (args.column_names.empty()) {
151	    for (const auto &column_name : existing_cf_names) {
152	      cf_descriptors.emplace_back(column_name, make_cf_options(column_name));
153	    }
154	  } else {
155	    bool has_default = false;
156	    for (const auto &column_name : args.column_names) {
157	      if (std::find(existing_cf_names.begin(), existing_cf_names.end(),
158	                    column_name) == existing_cf_names.end()) {
159	        LOG_ERROR("Column family[%s] does not exist in RocksDB[%s]",
160	                  column_name.c_str(), args.db_path.c_str());
161	        return Status::InvalidArgument();
162	      }
163	      if (column_name == rocksdb::kDefaultColumnFamilyName) {
164	        has_default = true;
165	      }
166	    }
167	    if (read_only) {
168	      for (const auto &column_name : args.column_names) {
169	        cf_descriptors.emplace_back(column_name, make_cf_options(column_name));
170	      }
171	      if (!has_default) {
172	        cf_descriptors.emplace_back(
173	            rocksdb::kDefaultColumnFamilyName,
174	            make_cf_options(rocksdb::kDefaultColumnFamilyName));
175	      }
176	    } else {
177	      for (const auto &column_name : existing_cf_names) {
178	        cf_descriptors.emplace_back(column_name, make_cf_options(column_name));
179	      }
180	    }
181	  }
182	
183	  rocksdb::DB *db;
184	  if (read_only) {
185	    s = rocksdb::DB::OpenForReadOnly(create_opts_, args.db_path, cf_descriptors,
186	                                     &cf_handles_, &db);
187	  } else {
188	    s = rocksdb::DB::Open(create_opts_, args.db_path, cf_descriptors,
189	                          &cf_handles_, &db);
190	  }
191	  if (!s.ok()) {
192	    LOG_ERROR("Failed to open RocksDB[%s], code[%d], reason[%s]",
193	              args.db_path.c_str(), s.code(), s.ToString().c_str());
194	    return Status::InternalError();
195	  }
196	
197	  db_.reset(db);
198	  read_only_ = read_only;
199	  write_opts_.disableWAL = true;
200	  LOG_DEBUG("Opened RocksDB[%s] with Args", args.db_path.c_str());
201	  return Status::OK();
202	}
