213	Status RocksdbContext::validate_and_set_db_path(const std::string &db_path,
214	                                                bool should_exist) {
215	  if (db_path.empty()) {
216	    LOG_ERROR("RocksDB path cannot be empty");
217	    return Status::InvalidArgument();
218	  }
219	
220	  if (FILE::IsExist(db_path)) {
221	    if (!should_exist) {
222	      LOG_ERROR("RocksDB path[%s] already exists", db_path.c_str());
223	      return Status::InvalidArgument();
224	    }
225	    if (!FILE::IsDirectory(db_path)) {
226	      LOG_ERROR("RocksDB path[%s] is not a directory", db_path.c_str());
227	      return Status::InvalidArgument();
228	    }
229	  } else {
230	    if (should_exist) {
231	      LOG_ERROR("RocksDB path[%s] does not exist", db_path.c_str());
232	      return Status::NotFound();
233	    }
234	  }
235	
236	  db_path_ = db_path;
237	  return Status::OK();
238	}
