410	Status RocksdbContext::create_cf(const std::string &cf_name) {
411	  std::lock_guard<std::mutex> lock(mutex_);
412	
413	  if (cf_name == rocksdb::kDefaultColumnFamilyName) {
414	    LOG_ERROR("Forbidden to create default cf in RocksDB[%s]",
415	              db_path_.c_str());
416	    return Status::InvalidArgument();
417	  }
418	
419	  for (auto cf_handle : cf_handles_) {
420	    if (cf_handle->GetName() == cf_name) {
421	      LOG_ERROR("Column family[%s] already exists in RocksDB[%s]",
422	                cf_name.c_str(), db_path_.c_str());
423	      return Status::InvalidArgument();
424	    }
425	  }
426	
427	  rocksdb::ColumnFamilyHandle *cf_handle{nullptr};
428	  rocksdb::ColumnFamilyOptions cf_options(create_opts_);
429	  // Apply per-CF merge operator if one was registered for this CF name
430	  auto it = per_cf_merge_ops_.find(cf_name);
431	  if (it != per_cf_merge_ops_.end() && it->second) {
432	    cf_options.merge_operator = it->second;
433	  }
434	  auto s = db_->CreateColumnFamily(cf_options, cf_name, &cf_handle);
435	  if (s.ok()) {
436	    cf_handles_.push_back(cf_handle);
437	    LOG_DEBUG("Created cf[%s] in RocksDB[%s]", cf_name.c_str(),
438	              db_path_.c_str());
439	    return Status::OK();
440	  } else {
441	    LOG_ERROR("Failed to create cf[%s] in RocksDB[%s], code[%d], reason[%s]",
442	              cf_name.c_str(), db_path_.c_str(), s.code(),
443	              s.ToString().c_str());
444	    return Status::InternalError();
445	  }
